import{_ as s,l as n,o as a,c as l,v as r,p as i,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"用户/内核分裂","description":"","frontmatter":{"title":"用户/内核分裂","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/user-kernel-split.md","filePath":"cs/user-kernel-split.md","lastUpdated":1789023840000}'),h={name:"cs/user-kernel-split.md"};function m(_,e,u,E,A,B){const o=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="用户-内核分裂" tabindex="-1">用户/内核分裂 <a class="header-anchor" href="#用户-内核分裂" aria-label="Permalink to &quot;用户/内核分裂&quot;">​</a></h1><div class="epigraph"><p>每个进程的虚空间常被切成用户一半与内核一半；系统调用不必换页表根，只需切特权。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Bovet and Cesati, Understanding the Linux Kernel 整理</footer></div><p><a href="/cs/addrspace-layout">上一课</a>已画出文本、数据、堆、栈，并点到「内核常在高半」。<a href="/cs/kernel-user">内核与用户态</a>讲的是特权门，不是这张图怎么切。<a href="/cs/paging-vm">分页</a>已能把任意虚页标成用户不可访问。缺口是<strong>分裂本身</strong>：为何内核映射进每个进程，用户指针与内核指针如何共存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>系统调用要读用户缓冲、要写页表，若内核活在另一套地址空间，每次陷入都换页表根，<a href="/cs/tlb-translate">TLB</a> 全作废。经典 Unix/Linux 选择：同一套页表里，高地址是内核，页表项清掉用户可访问位；低地址是该进程用户空间。缺口不是再导页表格式，而是约定这道分界，以及内核如何安全地解引用用户指针。</p><p>本课不把每种架构的分界数字当考纲。</p><p><span class="marginnote">32 位曾用 3G/1G；64 位用 canonical 空洞把用户与内核远远分开。对象仍是：内核代码在每个进程里都有翻译，用户走不到那些页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件用页表项的用户位执行分裂：用户态访问内核虚地址立即故障。<a href="/cs/syscall-path">系统调用路径</a>上，内核带着自己的指针跑，同时用 <code>copy_from_user</code> / <code>copy_to_user</code> 触及用户缓冲——那些函数先检查指针落在用户区间，再在故障时把缺页或坏地址变成错误码，而不是内核 oops。</p>',9)),(a(),i(p,null,{default:t(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E8%99%9A%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20SYSCALL%5B%22%E9%99%B7%E5%85%A5%3A%20%E4%BB%8D%E6%AD%A4%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%E8%99%9A%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20SYSCALL%0A%20%20SYSCALL%20--%3E%20COPY%5B%22copy_from_user%22%5D%0A%20%20COPY%20--%3E%20CHK%5B%22%E8%B6%8A%E7%95%8C%E5%88%99%E5%A4%B1%E8%B4%A5%2C%20%E4%B8%8D%E5%86%99%E5%86%85%E6%A0%B8%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分裂让内核成为「始终可见的那一半」：中断、系统调用、缺页入口都能用同一套内核符号。用户隔离仍靠<a href="/cs/paging-vm">分页</a>的用户位与各进程不同的低半页表，不靠再发明一套环。与特权课的分工：环决定「能不能执行 <code>csrrw satp</code>」；分裂决定「用户 load 能不能碰到内核数据」。</p><p>后课的 <code>brk</code> 只移动用户堆的上限，碰不到内核分界。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 KPTI 的侧信道对策全文，只承认：把内核从用户页表里拿掉会多一次页表切换，换 TLB 隔离。也不把模块加载的内核虚地址分配写完。用户/内核指针在类型上应分开；教学上记住「用户指针必须经拷贝路径」。</p><p>后课默认：合法用户虚区间在分界以下（或 canonical 用户半）。堆如何向高处申请，下一课 <code>brk</code> 与堆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核映射进每个进程的高半，陷入少换页表根。</li><li>用户位执行分裂；用户缓冲经拷贝路径进入内核。</li><li>堆上限如何移动是 <code>brk</code> 的缺口。</li><li>出处：Tanenbaum <em>MOS</em>；Bovet and Cesati, <em>ULK</em>；Love, <em>Linux Kernel Development</em>。</li></ul>',8))])}const b=s(h,[["render",m]]);export{T as __pageData,b as default};
